def parse(text: str) -> list[list[int]]:
    """Read a Sudoku puzzle from a string, returning a 9x9 grid of ints.
    Digits 1-9 are givens; 0 and '.' are empty cells.
    Whitespace is ignored.
    Raises ValueError if the input does not contain exactly 81 cells or invalid characters.
