    # Filter out whitespace and collect characters
    chars = [c for c in text if c not in " \t\n\r"]
    if len(chars) != 81:
        raise ValueError("Invalid number of cells")

    grid = [[0] * 9 for _ in range(9)]
    for idx, ch in enumerate(chars):
        if idx % 9 == 0:
            row = idx // 9
            if row >= 9:
                raise ValueError("More than 81 cells")
        if ch == '.':
            grid[row][idx % 9] = 0
        elif '1' <= ch <= '9':
            val = int(ch)
            if val < 1 or val > 9:
                raise ValueError("Invalid digit")
            grid[row][idx % 9] = val
        else:
            raise ValueError(f"Invalid character: {ch!r}")
    return grid


def to_string(grid) -> str:
    """Convert a 9x9 grid (list of lists of ints) to a single-line string.
    Empty cells are represented by '.', others by the digit.
    Returns a string of length 81.
    """
    out = []
    for row in grid:
        out.extend(str(x).replace('.', '.') if x != 0 else '.' for x in row)
    return ''.join(out)


