import re
from typing import Union, Tuple, List, Set, Iterable, Dict

class ErrorValue(str):
    """Error value subclass representing a cell's error state."""
    __slots__ = ()
    def __new__(cls, msg: str) -> "ErrorValue":
        return super().__new__(cls, msg)

    def __eq__(self, other):
        return isinstance(other, ErrorValue) and self == other or super().__eq__(other)


class FormulaError(ValueError):
    """Raised on syntax, parsing, or validation errors in formulas."""


def _upper(s: str) -> str:
    """Return upper-case version of s, used for canonical cell names."""
    return s.upper()


def _is_valid_cell(name: str) -> bool:
    """Validate cell name per problem statement.
    Returns True if name matches A-Z followed by 1-999, case-insensitive.
    """
    # cell = <letter> <row>
    match = re.match(r'^[A-Za-z]\d+$', name)
    if not match:
        return False
    col, row = match.groups()
    col = col.upper()
    row = int(row)
    if row < 1 or row > 999:
        return False
    return True


def _to_upper_canonical(name: str) -> str:
    """Convert any case/whitespace cell name to canonical upper-case."""
    s = name.strip().upper()
    if _is_valid_cell(s):
        return s
    return None


