            cols = sorted({c[0] for c in (c1, c2)})   # only A,B,... that appear
            cells = []
            for r in rows:
                for c in cols:
                    cell_name = f"{c}{r}"
                    if _is_valid_cell(cell_name):
                        cells.append(cell_name)
            # Order by row then column; we already iterate rows ascending and cols sorted ascending → correct row‑major.
            return cells

    # ---------- Main parsing ----------
    def parse_expr(i: int):
        nonlocal pos
        # parse term
        left = parse_term(i)
        while pos < n:
            op = peek(pos)
            if op in ('+', '-'):
                consume(pos)
                right = parse_term(pos)
                left = BinOpNode(op, left, right)
            elif op == ')':
                consume(pos)
                break
            else:
                raise FormulaError(f"unexpected token '{op}'")
        return left

    def parse_term(i: int):
        nonlocal pos
        left = parse_unary(i)
        while pos < n:
            op = peek(pos)
            if op in ('*', '/'):
                consume(pos)
                right = parse_unary(pos)
                left = BinOpNode(op, left, right)
            else:
                break
        return left

    def parse_unary(i: int):
        nonlocal pos
        # optional leading '+' or '-'
        if peek(pos) == '+':
            consume(pos)
            child = parse_unary(pos)
            return UnaryNode('+', child)
        if peek(pos) == '-':
            consume(pos)
            child = parse_unary(pos)
            return UnaryNode('-', child)
        # number
        val = parse_number(pos)
        return ConstNode(val)
        # reference
        if peek(pos) == '(':
            consume(pos)
            expr = parse_expr(pos)
            if peek(pos) != ')':
                raise FormulaError("missing closing parenthesis")
            consume(pos)
            return ParenNode(expr)
        # function call
        if peek(pos).isalpha():
            fname_start = pos
            while pos < n and src[pos].isalpha():
                pos += 1
            fname = src[fname_start:pos]
            if pos >= n or src[pos] != '(':
                raise FormulaError("function name must be followed by '('")
            pos += 1   # '('
            args = parse_function_args(pos)
            if pos >= n or src[pos] != ')':
                raise FormulaError("missing closing ')' for function")
            pos += 1   # ')'
            # Build CallNode
            call_args = []
            for arg in args:
                # Evaluate each argument lazily? For AST we just store the parsed sub‑AST; evaluation will happen later.
                call_args.append(arg)
            return CallNode(fname, call_args)
        raise FormulaError("unexpected token")

    # Start parsing
    root = parse_expr(0)
    if pos != n:
        raise FormulaError(f"unexpected characters after formula: {src[pos:]}")
    return root


# ---------- references ----------
def references(tree: object) -> Set[str]:
    """
    Walk the AST and collect all cell names that are directly referenced (including those inside ranges).
    Returns a set of canonical upper‑case cell names that are inside the sheet.
    """
    result: Set[str] = set()

    def walk(node):
        typ = getattr(node, "type", None)
        if typ is None:
            return
        if isinstance(node, ConstNode):
            return
        if isinstance(node, RefNode):
            result.add(node.name)
        elif isinstance(node, RangeNode):
            result.update(node.cells_in_order())
        elif isinstance(node, CallNode):
            # For a call, we also collect the ranges inside its arguments,
            # which will be covered by the range node handling above.
            for arg in node.args:   # args are themselves AST nodes (could be Const, Ref, Range, BinOp, etc.)
                walk(arg)
        elif isinstance(node, UnaryNode):
            walk(node.child)
        elif isinstance(node, BinOpNode):
            walk(node.left)
            walk(node.right)
        elif isinstance(node, ParenNode):
            walk(node.expr)
        else:
            raise RuntimeError(f"unknown node type {type(node)})")

    walk(tree)
    return result


# ---------- evaluate ----------
def evaluate(tree: object, lookup) -> Union[int, float, str, ErrorValue]:
    """
    Evaluate AST using lookup(name) → cell value (as stored in the sheet).
    Implements the rules from the problem statement, including the new error values.
    Returns the value; if the result is a number collection for functions, the appropriate error/value is returned.
    """
    # Helper: get value of a reference; return 0 if empty cell, otherwise cell value.
    def lookup_cell(name: str) -> Union[int, float, str, None, ErrorValue]:
        # lookup expects name (canonical upper-case)
        if name not in lookup:
            # cell does not exist (outside sheet)
            return None
        val = lookup(name)
        if val is None:
            # empty cell → treat as 0 for numeric contexts
            return 0
        if isinstance(val, ErrorValue):
            return val
        if isinstance(val, (int, float)):
            return val
        # text → treat as error for formulas that need a number
        return val   # will be caught later

    # Recursive evaluator; returns the evaluated value for the sub‑expression.
    def eval_node(node):
        typ = getattr(node, "type", None)
        if typ is None:
            return None
        if isinstance(node, ConstNode):
            # number literal
            return node.value
        if isinstance(node, RefNode):
            # reference: return lookup_cell(name)
            return lookup_cell(node.name)
        if isinstance(node, RangeNode):
            # range: we will collect numbers from its cells in row‑major order later; this is not a per‑cell evaluation.
            # In the context of evaluate, a RangeNode is only created as part of a CallNode; evaluate is called on the CallNode,
            # not directly on RangeNode. We'll leave this case unreachable.
            raise NotImplementedError("RangeNode should not be evaluated directly")
        if isinstance(node, CallNode):
            # evaluate arguments
            arg_results = []
            left_errors = []   # track the first error encountered (by precedence)
            for arg in node.args:
                # Evaluate argument (could be ConstNode, RefNode, RangeNode, BinOpNode, etc.)
                arg_val = eval_node(arg)
                # Determine if this argument caused an error or text that leads to #VALUE!
                # For CallNode, we need the raw result as defined:
                #   - If any argument yields an error value (including #REF! etc.), that error is the result.
                #   - Otherwise, if the argument is text, it yields #VALUE! (according to spec).
                #   - If the argument is a number, collect it.
                if isinstance(arg_val, ErrorValue):
                    # error propagates immediately
                    return arg_val
                # If arg_val is a string (text), that's #VALUE!
                if isinstance(arg_val, str):
                    # text -> #VALUE!
                    return ErrorValue("#VALUE!")
                # If arg_val is a number (int/float) or 0 (from empty cell), treat as number.
                arg_results.append(arg_val)
            # At this point we have a list of numbers (possibly empty).
            # Determine function result.
            fname = node.fname
            if fname == "SUM":
                total = sum(arg_results)
                # Sum rules: int if all are int, else float; 0 if none.
                if all(isinstance(v, int) and v != 0 for v in arg_results):
                    # all ints -> int
                    if total == 0:
                        # sum of zeros? but spec says 0 when none? Usually sum of zeros is zero, fine.
                        # But we just return int if all ints; if total is int due to integer division? Not needed.
                        return total
                    return int(total) if total.is_integer() else total   # total is float if mixed? We'll just return int if all ints and total is int.
                else:
                    return float(total) if total != int(total) else int(total)
                # Actually rule: "sum: an int when all are ints, else a float". We'll implement simple.
                # We'll just return total; later caller may cast? For correctness we follow spec.
                # We'll do:
                #   if all(isinstance(v, int)): return int(sum) else return float(sum)
                # But sum of ints is int; sum of floats is float.
                # We'll compute total using Python's sum which returns appropriate type.
                total = sum(arg_results)
                if isinstance(total, int):
                    # all operands were ints and no overflow? fine.
                    return total
                else:
                    return float(total)
            elif fname == "AVG":
                if not arg_results:
                    # no numbers -> division by zero -> #DIV/0!
                    return ErrorValue("#DIV/0!")
                total = sum(arg_results)
                count = len(arg_results)
                mean = total / count
                # Return float (even if integer, spec says AVG gives float)
                return float(mean)
            elif fname == "MIN":
                if not arg_results:
                    return 0   # "or 0 when there are none"
                else:
                    return min(arg_results)   # smallest number unchanged
            elif fname == "MAX":
                if not arg_results:
                    return 0
                else:
                    return max(arg_results)
            else:
                raise FormulaError(f"unknown function {fname}")
        if isinstance(node, UnaryNode):
            child_val = eval_node(node.child)
            if node.op == '+':
                return child_val
            else:   # '-'
                # unary minus: apply to child, but if child is error propagate error; if child is text -> #VALUE!; if child is number, negate.
                if isinstance(child_val, ErrorValue):
