                if isinstance(child_val, (int, float)):
                    return -child_val
                else:   # text -> #VALUE!
                    return ErrorValue("#VALUE!")
        if isinstance(node, BinOpNode):
            left_val = eval_node(node.left)
            right_val = eval_node(node.right)
            if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
                # Propagate the leftmost error
                if isinstance(left_val, ErrorValue):
                    return left_val
                else:
                    return right_val
            # Both are numbers (or 0 from empty cell, which is numeric)
            op = node.op
            if op == '+':
                res = left_val + right_val
                # Type rule
                if isinstance(left_val, int) and isinstance(right_val, int):
                    # integer addition -> int if result is integer (always true)
                    return int(res)
                elif isinstance(left_val, float) or isinstance(right_val, float):
                    return float(res)
                else:
                    return res   # mixed int/float -> float? we'll return float
            elif op == '-':
                res = left_val - right_val
                # same type rule
                if isinstance(left_val, int) and isinstance(right_val, int):
                    if res.is_integer():
                        return int(res)
                    else:
                        return res
                else:
                    return float(res)
            elif op == '*':
                res = left_val * right_val
                if isinstance(left_val, int) and isinstance(right_val, int):
                    # product of ints is int (but may be large; Python handles big ints fine)
                    return left_val * right_val
                else:
                    return left_val * right_val
            elif op == '/':
                if left_val == 0:
                    return ErrorValue("#DIV/0!")
                # Division always gives float
                return left_val / right_val
            else:
                raise RuntimeError(f"unknown binary operator {op}")
        raise RuntimeError(f"unknown node type {type(node)})")

    return eval_node(tree)
