from typing import Set, Iterable, Dict

class DependencyGraph:
    """
    Tracks precedents (cells a formula depends on) and dependents.
    All names are canonical upper‑case.
    """

    def __init__(self):
        self._precedents: Dict[str, Set[str]] = {}   # cell -> set of cells it directly depends on
        self._dependents: Dict[str, Set[str]] = {}   # cell -> set of cells that depend on it

    # set_dependencies(cell: str, precedents) replaces cell's precedents with the given iterable of names (empty removes them)
    def set_dependencies(self, cell: str, precedents: Iterable[str]) -> None:
        if not precedents:
            precedents = set()
        # Ensure the cell exists in the graph
        if cell not in self._precedents:
            self._precedents[cell] = set()
        # Filter and store only valid inside‑sheet references
        valid_pre = {p for p in precedents if _is_valid_cell(p.upper())}
        self._precedents[cell] = valid_pre

        # Update dependents for each predecessor
        for p in self._precedents[cell]:
            self._dependents.setdefault(p, set()).add(cell)

    # precedents(cell) -> set[str]
    def precedents(self, cell: str) -> Set[str]:
        return self._precedents.get(cell, set())

    # dependents(cell) -> set[str]
    def dependents(self, cell: str) -> Set[str]:
        return self._dependents.get(cell, set())

    # all_dependents(cell) -> set[str] gives every cell that refers to cell directly or through other cells.
    # It contains cell itself only when cell is on a cycle.
    def all_dependents(self, cell: str) -> Set[str]:
        # DFS from cell following reverse edges (dependents)
        visited = set()
        stack = [cell]
        while stack:
            cur = stack.pop()
            if cur in visited:
                continue
            visited.add(cur)
            # For each cell that depends on cur (i.e., cur is a precedent of that cell)
            for dep in self.dependents(cur):
                if dep not in visited:
                    stack.append(dep)
        return visited

    # cycle_cells() -> set[str] gives every cell that lies on a cycle.
    def cycle_cells(self) -> Set[str]:
        # Find cycles in the directed graph defined by precedents edges (A -> B if B is in precedents(A))
        graph = self._precedents   # cell -> set of cells it depends on
        WHITE, GRAY, BLACK = 0, 1, 2
        color = {}
        on_stack = {}
        cycles: Set[str] = set()

        def dfs(v):
            color[v] = GRAY
            on_stack[v] = True
            for nxt in graph.get(v, set()):
                if nxt not in color:
                    dfs(nxt)
                elif color[nxt] == GRAY:
                    # cycle found
                    # Mark all nodes currently in the recursion stack
                    stack_nodes = [u for u in color if color[u] == GRAY and on_stack[u]]
                    cycles.update(stack_nodes)
            color[v] = BLACK
            on_stack[v] = False

        for node in graph:
            if node not in color:
                dfs(node)
        return cycles
