                pass
            else:
                # not a number
                pass
            if isinstance(val, (int, float)):
                self._value[name_canonical] = val
                self._raw[name_canonical] = str(val)
                affected = self.graph.all_dependents(name_canonical) | {name_canonical}
                affected.sort(key=lambda s: (int(s[1:]), s[0]))
                return affected

        # Anything else (including regular text) is stored as plain text.
        self._value[name_canonical] = raw.strip()
        self._raw[name_canonical] = raw.strip()
        affected = self.graph.all_dependents(name_canonical) | {name_canonical}
        affected.sort(key=lambda s: (int(s[1:]), s[0]))
        return affected

    def get(self, name: str) -> Union[int, float, str, None, ErrorValue]:
        name_canonical = self._canonical_name(name)
        return self._value.get(name_canonical, None)

    def raw(self, name: str) -> str:
        name_canonical = self._canonical_name(name)
        return self._raw.get(name_canonical, '')

    def cells(self) -> List[str]:
