        non_empty = []
        for cell in self._value:
            val = self._value[cell]
            # Empty cell is '' or None
            if val == '' or val is None:
                continue
            non_empty.append(cell)
        non_empty.sort(key=lambda s: (int(s[1:]), s[0]))
        return non_empty

