    # Full recompute (as required by rule 1: after every set every cell's value is as if the whole sheet had been calculated from scratch)
    def _full_recompute(self):
        """Recompute the whole sheet from scratch, updating _value and counting evaluations."""
        # Collect all cells in row‑major order.
