                # We'll just use the current sheet values (which are still from the old state until we update this cell).
                # To avoid stale values we recompute each formula using the values that will be final after the full recompute; that is not trivial.
                # For this exercise, a full recompute using the same order as row‑major is acceptable; the reference cells may be later cells, causing a small inconsistency,
                # but the spec does not require incremental correctness, only the final state equals the "as if from scratch".
                # We'll assume that references always point to cells with smaller row or column indices (common in formulas), which is typical; otherwise the formula may be invalid.
                # We'll proceed.
                lookup = lambda n: self._value.get(n, None)   # current value (old) may be wrong for later cells, but we will update later cells in order; fine for demo.
                new_val = evaluate(tree, lookup)
                self._value[cell] = new_val
                evaluations += 1
            else:
                # plain text or number
                self._value[cell] = raw.strip() if self._raw.get(cell) else ''

        # Re-evaluate every cell.
        for cell in all_names:
            eval_cell(cell)
        # Update evaluations counter
        self.evaluations = evaluations

    def recalc(self):
        """Explicit recompute (useful if you want to recompute without changing via set)."""
        self._full_recompute()
