            description = room_info.get("description")
            exits = room_info.get("exits", {})
            item_ids = room_info.get("items", ())
            locks = room_info.get("locks", {})

            if not name or not description:
                raise WorldError(f"Room '{room_id}' lacks name or description.")

            # Validate exits
            for d in exits:
                exit_def = exits[d]
                if isinstance(exit_def, dict):
                    # locked exit dict
                    if "to" not in exit_def or "key" not in exit_def:
                        raise WorldError(f"Exit '{d}' lacks 'to' or 'key'.")
                    target = exit_def["to"]
                    key_item = exit_def["key"]
                    if target not in data["rooms"]:
                        raise WorldError(f"Exits from '{room_id}' references unknown room '{target}'.")
                    if key_item not in data["items"]:
                        raise WorldError(f"Key item '{key_item}' not defined.")
                else:
                    # plain room id (unlocked exit)
                    if d not in DIRECTIONS:
                        raise WorldError(f"Direction '{d}' is not valid.")
                    target = exit_def
                    if target not in data["rooms"]:
                        raise WorldError(f"Exits from '{room_id}' references unknown room '{target}'.")
                    key_item = None   # unlocked

                # Record exit for this room
                rooms[room_id].exits[d] = target
                rooms[room_id].locks[d] = key_item   # None for unlocked

            rooms[room_id] = Room(
                id=room_id,
                name=name,
                description=description,
                exits=exits,
                locks=locks,
                items=tuple(item_ids),
            )

        # ----- items -----
        items = {}
        for item_id, item_info in data.get("items", {}).items():
            name = item_info.get("name")
            desc = item_info.get("description")
            portable = item_info.get("portable", True)
            treasure = item_info.get("treasure", 0)

            if not name:
                raise WorldError(f"Item '{item_id}' lacks name.")
            if not desc:
                raise WorldError(f"Item '{item_id}' lacks description.")
            if not isinstance(portable, bool):
                raise WorldError(f"Item '{item_id}' portable must be a bool.")
            if not isinstance(treasure, int) or treasure < 0:
                raise WorldError(f"Item '{item_id}' treasure must be a non‑negative integer.")

            items[item_id] = Item(
                id=item_id,
                name=name,
                description=desc,
                portable=portable,
                treasure=treasure,
            )

        # Verify that every lock key maps to a valid item id
        for room_id, room in rooms.items():
            for d, key_item in room.locks.items():
                if key_item is None:
                    continue
                if key_item not in items:
                    raise WorldError(f"Lock key '{key_item}' for room '{room_id}' refers to undefined item.")

        return cls(start, rooms, items)
